LogicDefinition.ScriptText:
#load "reference"
using FS.SDK;
using FS.SDK.Components;



//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           Processing iO / NiO Part                                                             //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//
//    28.07.2025       1.5.3          Grob (CN)        Template erstellt
//    08.08.2025       1.6.0          Grob (CN)        Steuerung über PLC und manueller Eingriff NiO
//    04.12.2025       1.1.0          Egg              Überarbeitung und Code Optimierung
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//
//    FEE              X              CN               
/*
//============================================================================================================
//
//    Beschreibung:
//
//    Die Logik gibt anhand der Vorgabe "PAR_Percentage_Ok_Limit" (1-100%) per Zufall ein iO-String oder 
//    NiO-String zurück.
//    Zudem kann das Material und das Mark entsprechend der iO-/NiO-Bearbeitung geändert werden.
//
//============================================================================================================
//
//    Voraussetzung/Benutzte Slots:
//      
//    PAR_ResultString_Ok: String für iO Bearbeitung
//    PAR_ResultString_Nok: String für NiO Bearbeitung
//    
//
//    PAR_Percentage_Ok_Limit: 1-100 %
//    PAR_MarkToDetect: Logik sucht nach Mark. Wird dieses gefunden, wird das Mark des entsprechenden Objekts 
//                      umbenannt oder das Material geändert.
//
//    PAR_UseChangeMark: Anwahl der Umbennung des Marks. Mark wird je nach iO oder NiO umbenannt
//    PAR_NewMark_Ok: Neues Mark bei iO-Bearbeitung
//    PAR_NewMark_Nok: Neues Mark bei NiO-Bearbeitung
//
//    PAR_UseChangeMaterial: Anwahl zum Ändern des Materials anhand einer iO- oder NiO-Bearbeitung
//    PAR_NewMaterial_Ok: Neues Material bei iO-Bearbeitung
//    PAR_NewMaterial_Nok: Neues Material bei NiO-Bearbeitung
//    
//    
//    Output Slot Values
//
//    SIM_MarkChanged: Mark wurde geändert
//    SIM_MaterialChanged: Material wurde geändert
//============================================================================================================
*/
//////////////////////////////////////////////////////////////////////////////////////////////////////////////


// Check Mark-/Material-Strings not empty
if(string.IsNullOrWhiteSpace(PAR_MarkToDetect)) return;
if(string.IsNullOrWhiteSpace(PAR_NewMark_Ok)) return;
if(string.IsNullOrWhiteSpace(PAR_NewMark_Nok)) return;
if(string.IsNullOrWhiteSpace(PAR_NewMaterial_Ok)) return;
if(string.IsNullOrWhiteSpace(PAR_NewMaterial_Nok)) return;

// Default Fehler Meldung
SIM_Fault = string.Empty;

if (PAR_Percentage_Ok_Limit < 0 || PAR_Percentage_Ok_Limit > 100)
{
    SIM_Fault = "Percentage Ok Limit außerhalb Bereich (0% - 100%)";
    return;
}


Random rand = new Random();


// Get CollisionList of Parent
var sensor = SceneObject.Parent;
if(sensor == null) return;

var collision = sensor.GetComponent<ColliderComponent>();
if(collision == null) return;

var listcol = collision.CollisionList;



if (SIM_Trigger && !_triggerState)
{

    int randNumber = rand.Next(1,101);

    // Ergebnis iO
    if(randNumber >= 1 && randNumber <= PAR_Percentage_Ok_Limit || PAR_EnablePlcControl && PLC_ControlState == 2)
    {
        SIM_Result_Ok = true;
        SIM_Result_Nok = false;
        SIM_ResultString = PAR_ResultString_Ok;
    }

    // Ergebnis NiO
    if(randNumber >= 1 && randNumber <= PAR_Percentage_Ok_Limit || PAR_EnablePlcControl && PLC_ControlState == 3 || PAR_SetManualNok)
    {
        SIM_Result_Ok = false;
        SIM_Result_Nok = true;
        SIM_ResultString = PAR_ResultString_Ok;
    }


    if(listcol.Any())
    {
        // Alle Objekte mit definiertem Mark identifizieren
        var relevantObjects = listcol.Where(x => x.MarkComponent.Mark == PAR_MarkToDetect);    

        foreach (var el in relevantObjects)
        {
            // Change Mark
            if (PAR_UseChangeMark)
            {
                el.MarkComponent.Mark = SIM_Result_Ok ? PAR_NewMark_Ok : PAR_NewMark_Nok;
                SIM_MarkChanged = true;
            }
            else
            {
                SIM_MarkChanged = false;
            }
            // Change Material
            if (PAR_UseChangeMaterial)
            {
                el.GetComponent<ModelComponent>().CurrentMaterial = SIM_Result_Ok ?  PAR_NewMaterial_Ok : PAR_NewMaterial_Nok;
                SIM_MaterialChanged = true;
            }
            else
            {
                SIM_MaterialChanged = false;
            }
        }
    }



}
_triggerState = SIM_Trigger;
